INSERT INTO `announcements` (`id`, `title`, `content`, `is_important`, `created_at`, `dorm_id`, `category`, `is_active`) VALUES
(1, '📢 แจ้งกำหนดการล้างถังพักน้ำและตรวจสอบระบบประปาหอพัก', 'ทางหอพักเกษตร 2 จะดำเนินการล้างถังพักน้ำประจำปี ในวันเสาร์ที่ 29 สิงหาคม 2569 เวลา 09:00 - 14:00 น. ขอให้ลูกหอทุกท่านสำรองน้ำใช้ล่วงหน้า ขออภัยในความไม่สะดวกครับ', 1, '2026-08-24 07:55:46', 1, 'announcement', 1),
(2, '⚡ แจ้งชำระค่าเช่าและค่าน้ำ-ไฟ ประจำรอบเดือนสิงหาคม 2569', 'บิลค่าเช่าประจำเดือนสิงหาคม 2569 ได้ออกเรียบร้อยแล้ว ลูกหอสามารถเข้าดูยอดและสแกน QR Code พร้อมเพย์ตามยอดบิลจริงผ่านระบบ SmartDom ได้ตั้งแต่วันนี้จนถึงสิ้นเดือนครับ', 1, '2026-08-24 07:55:46', 1, 'billing', 1),
(3, '📶 อัปเกรดระบบอินเทอร์เน็ต Wi-Fi 6 ความเร็วสูงทุกชั้น', 'หอพักได้ติดตั้งจุดกระจายสัญญาณ Wi-Fi 6 เพิ่มเติมบริเวณโถงทางเดินชั้น 1-4 เรียบร้อยแล้ว เพื่อรองรับการเรียนออนไลน์และทำงานได้อย่างเสถียรยิ่งขึ้น', 0, '2026-08-24 07:55:46', 1, 'facility', 1),
(4, '🧹 กำหนดการฉีดพ่นยากันยุงและแมลงบริเวณรอบอาคาร', 'วันอาทิตย์นี้เวลา 16:00 น. จะมีการฉีดพ่นละอองฝอยกำจัดยุงลายรอบบริเวณหอพักและที่จอดรถ กรุณาปิดหน้าต่างห้องพักของท่าน', 0, '2026-08-24 07:55:46', 1, 'announcement', 1);
